def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = [sum(v == color for row in g for v in row) for color in range(10)]
    bg = max(range(10), key=lambda color: counts[color])

    # Find the full-width colored barrier.
    marker = next((r for r, row in enumerate(g)
                   if row[0] != bg and all(v == row[0] for v in row)), None)
    if marker is None:
        return g
    marker_color = g[marker][0]
    object_colors = [c for c in range(10) if c != bg and c != marker_color and counts[c] > 0]
    if not object_colors:
        return g
    obj_color = max(object_colors, key=lambda c: counts[c])
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == obj_color]
    if not pts:
        return g

    top = min(r for r, _ in pts)
    bottom = max(r for r, _ in pts)
    if bottom < marker:
        # Move down until the object's bottom is adjacent to the barrier.
        delta = marker - 1 - bottom
        trailing_line = top + delta - 1
    elif top > marker:
        # Move up until the object's top is adjacent to the barrier.
        delta = marker + 1 - top
        trailing_line = bottom + delta + 1
    else:
        return g

    for r, c in pts:
        g[r][c] = bg
    for r, c in pts:
        nr = r + delta
        if 0 <= nr < h and g[nr][c] != marker_color:
            g[nr][c] = obj_color
    if 0 <= trailing_line < h:
        g[trailing_line] = [8] * w
    return g
